(() => {
let observer;
const attach=()=>{observer?.disconnect();const home=document.querySelector('.finvera-home');if(!home)return;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;if(reduced||!('IntersectionObserver' in window)){home.classList.remove('motion-ready');return}const sections=home.querySelectorAll('.lp-section,.blue-section,.final-cta,.native-guide');observer=new IntersectionObserver(entries=>{for(const e of entries){if(e.isIntersecting){e.target.classList.add('is-visible')}else if(e.boundingClientRect.bottom<=0||e.boundingClientRect.top>=window.innerHeight){e.target.classList.remove('is-visible')}}},{threshold:.08});for(const section of sections){section.classList.add('motion-reveal');observer.observe(section)}home.classList.add('motion-ready');for(const d of home.querySelectorAll('.feature-accordion'))d.addEventListener('toggle',()=>{if(d.open)for(const other of home.querySelectorAll('.feature-accordion'))if(other!==d)other.open=false});};
const app=document.getElementById('app');new MutationObserver(attach).observe(app,{childList:true});attach();matchMedia('(prefers-reduced-motion: reduce)').addEventListener('change',attach);window.addEventListener('pagehide',()=>observer?.disconnect());window.addEventListener('pageshow',attach);
})();